  (() => {
    const context = $json;
    const normalized = context.validation.normalized_result;
    const sampleIndices = (length) => [...new Set([0, 1, Math.floor(length / 2), length - 2, length - 1]
      .filter((index) => index >= 0 && index < length))];
    const collectionName = context.mission_type === 'invoice_extraction' ? 'invoices' : 'rows';
    const bilingualField = {
      bulk_categorization: 'description',
      plan_actual_deviation: 'cost_center',
      duplicate_payment_hunt: 'vendor',
      invoice_extraction: 'text',
    }[context.mission_type] ?? 'description';
    const compactTaskVariant = (variant, difficulty) => {
      const content = variant?.content ?? {};
      const caseDe = Array.isArray(content.case_data?.de) ? content.case_data.de : [];
      const caseEn = Array.isArray(content.case_data?.en) ? content.case_data.en : [];
      const sample = sampleIndices(Math.max(caseDe.length, caseEn.length)).map((index) => ({
        index,
        source_path_de: '/variants/' + difficulty + '/' + collectionName + '/' + index + '/' + bilingualField + '_de',
        source_path_en: '/variants/' + difficulty + '/' + collectionName + '/' + index + '/' + bilingualField + '_en',
        de: caseDe[index] ?? null,
        en: caseEn[index] ?? null,
      }));
      return {
        title_de: variant?.title_de,
        title_en: variant?.title_en,
        description_de: variant?.description_de,
        description_en: variant?.description_en,
        task_de: content.task?.de,
        task_en: content.task?.en,
        case_format: content.case_format,
        dataset: { rows_de: caseDe.length, rows_en: caseEn.length, sample },
        result_fields: (Array.isArray(content.result_fields) ? content.result_fields : []).map((field) => ({
          id: field.id,
          type: field.type,
          label: field.label,
          unit: field.unit,
        })),
        micro_learning_de: content.micro_learning?.de,
        micro_learning_en: content.micro_learning?.en,
      };
    };
    let mission = normalized;
    if (context.output_type === 'task_mission' && normalized?.variants) {
      mission = {
        representation_note: 'Canonical review projection; no duplicate compatibility fields are present.',
        mission_type: context.mission_type ?? normalized.mission_type ?? null,
        topic_de: normalized.topic_de ?? null,
        topic_en: normalized.topic_en ?? null,
        learning_objective_de: normalized.learning_objective_de ?? null,
        learning_objective_en: normalized.learning_objective_en ?? null,
        scheduled_date: normalized.scheduled_date ?? context.scheduled_date,
