  ? body.context_by_requirement
  : {};
const output = [];
for (const requirement of requirements) {
  const requests = Array.isArray(requirement.generator_requests) ? requirement.generator_requests : [];
  const researchContext = requirement.output_type === 'quiz_mission'
    ? (contextByRequirement[String(requirement.id)] ?? null)
    : null;
  for (let index = 0; index < requests.length; index += 1) {
    const request = requests[index] ?? {};
    output.push({ json: {
      generation_run_id: body.generation_run_id,
      orchestrator_execution_id: $execution.id,
      requirement_id: requirement.id,
      output_type: requirement.output_type ?? null,
      scheduled_date: requirement.scheduled_date ?? null,
      mission_type: requirement.mission_type ?? null,
      call_index: index,
      expected_calls: requests.length,
      difficulty: request.difficulty ?? null,
      research_context: researchContext,
      ai_request: request,
    } });
  }
}
return output;

