const start = $('Start Generation V2').first().json;
const body = start.body ?? start;
const requirements = Array.isArray(body.requirements) ? body.requirements : [];
const quizRequirements = requirements.filter((item) => item?.output_type === 'quiz_mission');
const isWeekly = body.generation_kind === 'weekly_missions';
const maximum = !isWeekly || quizRequirements.length === 0
  ? 0
  : quizRequirements.length >= 4
    ? 3
    : Math.min(2, quizRequirements.length);

return [{ json: {
  generation_run_id: body.generation_run_id,
  generation_kind: body.generation_kind,
  as_of: new Date().toISOString(),
  max_research_missions: maximum,
  preferred_tags: [
    'ai_governance', 'generative_ai', 'human_review', 'output_verification',
    'operational_resilience', 'risk', 'banking'
  ],
  requirements: requirements.map((requirement) => ({
    id: requirement.id,
    scheduled_date: requirement.scheduled_date ?? null,
    output_type: requirement.output_type ?? null,
    requested_mission_type: requirement.requested_mission_type ?? null,
    mission_type: requirement.mission_type ?? null,
  })),
} }];

const start = $('Start Generation V2').first().json;
const body = start.body ?? start;
const prepared = $('Prepare Research Selection').first().json;
const response = $json && typeof $json === 'object' ? $json : {};
const validResponse = response.status === 'completed'
  && Array.isArray(response.research_context)
  && response.context_by_requirement
  && typeof response.context_by_requirement === 'object';
const researchContext = validResponse ? response.research_context : [];
const contextByRequirement = validResponse ? response.context_by_requirement : {};
const transportError = response.error?.message ?? response.error ?? response.message ?? null;
const warnings = validResponse
  ? (Array.isArray(response.warnings) ? response.warnings.map(String) : [])
  : ['Research selector unavailable; continuing with evergreen mission generation.'
      + (transportError ? ' ' + String(transportError).slice(0, 300) : '')];

return [{ json: {
  ...body,
  research_context: researchContext,
  context_by_requirement: contextByRequirement,
  research_selection: {
    requested_maximum: prepared.max_research_missions,
    selected_count: researchContext.length,
    eligible_pool_count: validResponse ? Number(response.eligible_pool_count ?? 0) : 0,
    unmatched_quiz_requirement_ids: validResponse && Array.isArray(response.unmatched_quiz_requirement_ids)
      ? response.unmatched_quiz_requirement_ids.map(String)
      : [],
    warnings,
    selector_status: validResponse ? 'completed' : 'fallback',
  },
} }];
